 if(type==='tank'){rect(10,40,410,250);circle(10,5,410,80);circle(10,215,410,280)}
 else if(type==='ambient'){line(70,140,300,140);line(250,90,310,140);line(250,190,310,140);text(180,105,'ATM')}
 else if(type==='manual-ball'){ball();line(210,105,210,55);line(165,55,255,55)}
 else if(type==='pneumatic-ball'){ball();line(210,105,210,45);circle(195,15,225,45,'solid',false)}
