function point(svg:SVGSVGElement,clientX:number,clientY:number){const p=new DOMPoint(clientX,clientY),ctm=svg.getScreenCTM();return ctm?p.matrixTransform(ctm.inverse()):p}
function nextTag(prefix:string,nodes:Node[]){const escaped=prefix.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),pattern=new RegExp(`^${escaped}-(\\d+)$`,'i'),used=new Set(nodes.flatMap(node=>{const match=node.tag.match(pattern);return match?[Number(match[1])]:[]}));let serial=1;while(used.has(serial))serial++;return`${prefix}-${serial}`}
function nextContinuationTag(nodes:Node[]){const counts=new Map<number,number>();nodes.filter(n=>n.symbolType==='continuation').forEach(n=>{const id=Number(n.tag);if(Number.isInteger(id)&&id>0)counts.set(id,(counts.get(id)??0)+1)});const unmatched=[...counts].filter(([,count])=>count===1).map(([id])=>id).sort((a,b)=>a-b)[0];if(unmatched)return String(unmatched);let id=1;while((counts.get(id)??0)>=2)id++;return String(id)}
