 edges=edges.map(e=>({...e,from:e.fromPort==='actuator'?`${e.from}:actuator`:e.from,to:e.toPort==='actuator'?`${e.to}:actuator`:e.to}));
 nodes=[...nodes,...actuators.map(n=>({id:`${n.id}:actuator`,kind:'ambient' as const,boundary:'ambient' as const,tag:'',x:n.x,y:n.y}))];
