 const continuations=new Map<string,Node[]>();nodes.filter(n=>n.symbolType==='continuation').forEach(n=>continuations.set(n.tag,[...(continuations.get(n.tag)??[]),n]));continuations.forEach(group=>{for(let i=1;i<group.length;i++){link(group[0].id,{other:group[i].id});link(group[i].id,{other:group[0].id})}})
 const tankSources=nodes.filter(n=>n.kind==='tank'&&(n.tankRole==='source'||n.boundary==='supply'||n.transientSource)),exhaustSources=nodes.filter(n=>n.fluid==='Exhaust'&&n.kind!=='junction'&&n.boundary!=='ambient'&&!tankSources.some(source=>source.id===n.id)),sources=[...tankSources,...exhaustSources].sort((a,b)=>(b.pressure??0)-(a.pressure??0)),nodeFluids=new Map<string,string>(),edgeFluids=new Map<string,string>()
