function actuatorSolenoids(valve:Node,nodes:Node[],edges:Edge[]){
 return actuatorPaths(valve,nodes,edges).map(p=>p.node);
}
function solenoidFor(valve:Node,nodes:Node[],edges:Edge[]){return linkedSolenoid(valve,nodes,edges)}
