 const errors:string[]=[],pressures=roughSopPressures(nodes,edges),commands=new Set(actions.filter(a=>a.type==='open'||a.type==='close').map(a=>a.target));
 for(const valve of nodes.filter(n=>n.symbolType==='pneumatic-ball')){const solenoid=solenoidFor(valve,nodes,edges);if(!commands.has(valve.id)&&!(solenoid&&commands.has(solenoid.id)))continue;if(!solenoid){errors.push(`${valve.tag}: no connected solenoid. Connect its actuator port or choose a solenoid.`);continue}if(!(pressures.get(solenoid.id)!>0))errors.push(`${valve.tag} [${solenoid.tag}]: no pressurized actuation fluid reaches the solenoid. Check its supply valves and regulator setpoint.`)}
